typedef float rational_t;

struct vector3d {
    float x;
    float y;
    float z;
};

class ai_polypath_cell;

class ai_polypath_heap {
public:
    int session_id() const;
    const vector3d& goal() const;
    void add_cell(ai_polypath_cell* cell);
    void adjust_cell(ai_polypath_cell* cell);
};

class ai_polypath_cell {
public:
    bool query_for_path(
        ai_polypath_heap* heap,
        ai_polypath_cell* caller,
        rational_t arrivalcost
    ) __asm__("query_for_path__16ai_polypath_cellP16ai_polypath_heapP16ai_polypath_cellf");
    void compute_heuristic(const vector3d& goal);

private:
    char pad0[148];
    ai_polypath_cell* m_Link[3];
    int m_SessionID;
    rational_t m_ArrivalCost;
    rational_t m_Heuristic;
    bool m_Open;
    int m_ArrivalWall;
};

bool ai_polypath_cell::query_for_path(ai_polypath_heap* heap, ai_polypath_cell* caller, rational_t arrivalcost)
{
	if (m_SessionID!=heap->session_id())
	{
		// this is a NEW session, reset our internal data
		m_SessionID = heap->session_id();

		if (caller)
		{
			m_Open  = true;
			compute_heuristic(heap->goal());
			m_ArrivalCost = arrivalcost;

			// remember the side this caller is entering from
			if (caller == m_Link[0])
			{
				m_ArrivalWall = 0;
			}
			else if (caller == m_Link[1])
			{
				m_ArrivalWall = 1;
			}
			else if (caller == m_Link[2])
			{
				m_ArrivalWall = 2;
			}
		}
		else
		{
			// we are the cell that contains the starting location
			// of the A* search.
			m_Open  = false;
			m_ArrivalCost = 0;
			m_Heuristic = 0;
			m_ArrivalWall = 0;
		}

		// add this cell to the Open heap
		heap->add_cell(this);

		return(true);
	}
	else if (m_Open)
	{
		// m_Open means we are already in the Open Heap.
		// If this NEW caller provides a better path, adjust our data
		// Then tell the Heap to resort our position in the list.
		if ((arrivalcost + m_Heuristic) < (m_ArrivalCost + m_Heuristic))
		{
			m_ArrivalCost = arrivalcost;

			// remember the side this caller is entering from
			if (caller == m_Link[0])
			{
				m_ArrivalWall = 0;
			}
			else if (caller == m_Link[1])
			{
				m_ArrivalWall = 1;
			}
			else if (caller == m_Link[2])
			{
				m_ArrivalWall = 2;
			}

			// ask the heap to resort our position in the priority heap
			heap->adjust_cell(this);

			return(true);
		}
	}
	// this cell is closed
	return(false);
}
